python3 - <<'EOF'
import re
path = "prtech/techLEF/N551P6M.lef"
layers = []
cur = None
for line in open(path):
    s = line.strip()
    m = re.match(r'^LAYER\s+(\S+)', s)
    if m:
        cur = {"name": m.group(1)}
        layers.append(cur)
        continue
    if cur is not None:
        for key in ("TYPE","DIRECTION","PITCH","WIDTH","SPACING","RESISTANCE","OFFSET","AREA","MAXWIDTH","MINENCLOSEDAREA","DCCURRENTDENSITY"):
            if s.startswith(key+" ") or s == key:
                cur.setdefault(key, s)
